import{_ as t,o as r,c as a,ak as i}from"./chunks/framework.erqISGpw.js";const m=JSON.parse('{"title":"Devices","description":"","frontmatter":{},"headers":[],"relativePath":"prerequisites/devices.md","filePath":"prerequisites/devices.md","lastUpdated":1781468762000}'),o={name:"prerequisites/devices.md"};function s(d,e,n,c,h,l){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="devices" tabindex="-1">Devices <a class="header-anchor" href="#devices" aria-label="Permalink to &quot;Devices&quot;">​</a></h1><p>Here is an overview of devices supported by OpenMQTTGateway:</p><h2 id="for-radio-frequency-devices" tabindex="-1">For radio frequency devices <a class="header-anchor" href="#for-radio-frequency-devices" aria-label="Permalink to &quot;For radio frequency devices&quot;">​</a></h2><p>OpenMQTTGateway can support a wide range of 433mhz/315mhz devices, all the ones with SC5262 / SC5272, HX2262 / HX2272, PT2262 / PT2272, EV1527, RT1527, FP1527, HS1527 chipsets are supported by the RF gateway. Added to that RF2 support Kaku and Pilight an <a href="https://wiki.pilight.org/devices" target="_blank" rel="noreferrer">huge list</a>. Note that for the moment RF, RF2 and Pilight can not be activated on the same boards together.</p><h2 id="for-ble-devices" tabindex="-1">For BLE devices <a class="header-anchor" href="#for-ble-devices" aria-label="Permalink to &quot;For BLE devices&quot;">​</a></h2><p>OpenMQTTGateway is able to scan all the BLE devices that advertise their data so as to do presence detection. Added to that it retrieves the measures from the devices mentioned and linked to below. By default the data are read from the advertisements (no or very little impact on device battery life). For some devices we may connect briefly only to retrieve one or several parameters.</p><p>OpenMQTTGateway currently supports the decoding of <a href="https://decoder.theengs.io/devices/devices.html" target="_blank" rel="noreferrer">more than 100 Bluetooth devices</a>, which include popular devices like Mi Flora, Xiaomi scales, Inkbird, Govee and ThermoPro thermo-hygrometers and BBQ thermometers, SwitchBot devices status and many more.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li>(2) See <a href="https://github.com/atc1441/ATC_MiThermometer" target="_blank" rel="noreferrer">https://github.com/atc1441/ATC_MiThermometer</a></li><li>(3) See <a href="https://github.com/pvvx/ATC_MiThermometer" target="_blank" rel="noreferrer">https://github.com/pvvx/ATC_MiThermometer</a></li></ul></div><h2 id="for-infrared-ir-devices" tabindex="-1">For infrared IR devices <a class="header-anchor" href="#for-infrared-ir-devices" aria-label="Permalink to &quot;For infrared IR devices&quot;">​</a></h2><p>The list of supported devices for ESP is <a href="https://github.com/crankyoldgit/IRremoteESP8266/blob/master/SupportedProtocols.md" target="_blank" rel="noreferrer">here</a>, and <a href="https://github.com/1technophile/OpenMQTTGateway/blob/6f73160d1421bebf2c1bbc9b8017978ff5b16520/main/config_IR.h#L123" target="_blank" rel="noreferrer">here</a> for Arduino boards, as there is also the possibility of using raw and global cache (ESP) sending possibilities of this gateway is huge!</p><h2 id="lora" tabindex="-1">LORA <a class="header-anchor" href="#lora" aria-label="Permalink to &quot;LORA&quot;">​</a></h2><p>LoRa is more dedicated at this moment for tinkering and DIY and there is no Off the shelves devices compatible to my knowledge with this gateway.</p>',12)])])}const f=t(o,[["render",s]]);export{m as __pageData,f as default};
